import time, random
from random import Random
_rand = Random(12345)
def _prio(): return _rand.getrandbits(30)

# node = (key, prio, left, right, size, payload)
def _sz(n): return 0 if n is None else n[4]

def tinsert(n, key, payload, prio):
    if n is None:
        return (key, prio, None, None, 1, payload)
    k = n[0]
    if key < k:
        m = tinsert(n[2], key, payload, prio)
        if m[1] > n[1]:
            r2 = (k, n[1], m[3], n[3], _sz(m[3]) + 1 + _sz(n[3]), n[5])
            return (m[0], m[1], m[2], r2, _sz(m[2]) + 1 + _sz(r2), m[5])
        return (k, n[1], m, n[3], n[4] + 1, n[5])
    else:
        m = tinsert(n[3], key, payload, prio)
        if m[1] > n[1]:
            l2 = (k, n[1], n[2], m[2], _sz(n[2]) + 1 + _sz(m[2]), n[5])
            return (m[0], m[1], l2, m[3], _sz(l2) + 1 + _sz(m[3]), m[5])
        return (k, n[1], n[2], m, n[4] + 1, n[5])

def tmerge(a, b):
    if a is None: return b
    if b is None: return a
    if a[1] >= b[1]:
        m = tmerge(a[3], b)
        return (a[0], a[1], a[2], m, a[4] - _sz(a[3]) + _sz(m), a[5])
    else:
        m = tmerge(a, b[2])
        return (b[0], b[1], m, b[3], b[4] - _sz(b[2]) + _sz(m), b[5])

def tdelete(n, key):
    if n is None: return None, None
    k = n[0]
    if k < key:
        if n[2] is None: return n, None
        m, pl = tdelete(n[2], key)
        if m is n[2]: return n, None
        return (k, n[1], m, n[3], n[4] - 1, n[5]), pl
    if key < k:
        if n[3] is None: return n, None
        m, pl = tdelete(n[3], key)
        if m is n[3]: return n, None
        return (k, n[1], n[2], m, n[4] - 1, n[5]), pl
    return tmerge(n[2], n[3]), n[5]

def tpopmin(n):
    if n[2] is None:
        return n[3], n[0], n[5]
    m, key, pl = tpopmin(n[2])
    return (n[0], n[1], m, n[3], n[4] - 1, n[5]), key, pl

def tcount_lt(n, key):
    cnt = 0
    while n is not None:
        if n[0] < key:
            cnt += _sz(n[2]) + 1
            n = n[3]
        else:
            n = n[2]
    return cnt

def tupdate(n, key, payload):
    if n is None: return None
    k = n[0]
    if k < key:
        if n[3] is None: return n
        m = tupdate(n[3], key, payload)
        if m is n[3]: return n
        return (k, n[1], n[2], m, n[4], n[5])
    if key < k:
        if n[2] is None: return n
        m = tupdate(n[2], key, payload)
        if m is n[2]: return n
        return (k, n[1], m, n[3], n[4], n[5])
    return (k, n[1], n[2], n[3], n[4], payload)

def tget(n, key):
    while n is not None:
        k = n[0]
        if k < key: n = n[3]
        elif key < k: n = n[2]
        else: return n[5]
    return None

N = 60000
t0=time.perf_counter()
root = None
keys = list(range(N))
random.Random(7).shuffle(keys)
for k in keys:
    root = tinsert(root, k, k, _prio())
t1=time.perf_counter()
print("insert 60k: %.3fs -> %.1f us/op" % (t1-t0, (t1-t0)/N*1e6))
print("depth check: size", root[4])
# popmin
t0=time.perf_counter()
for i in range(N//2):
    root, k, pl = tpopmin(root)
t1=time.perf_counter()
print("popmin 30k: %.3fs -> %.1f us/op" % (t1-t0, (t1-t0)/(N//2)*1e6))
t0=time.perf_counter()
c=0
for i in range(N):
    c += tcount_lt(root, (i*7919%30000, -1))
t1=time.perf_counter()
print("count_lt 60k: %.3fs -> %.1f us/op" % (t1-t0, (t1-t0)/N*1e6))
# measure max depth
def depth(n):
    if n is None: return 0
    return 1+max(depth(n[2]), depth(n[3]))
import sys
sys.setrecursionlimit(100000)
print("max depth:", depth(root))
